import{_ as t,o as e,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const s="/assets/plates-bom-page.3a07cf64.svg",b=JSON.parse('{"title":"Plates BoM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/plates_bom/index.md","filePath":"guide/reports/plates_bom/index.md","lastUpdated":1790346505000}'),r={name:"guide/reports/plates_bom/index.md"},n=o('<h1 id="plates-bom" tabindex="-1">Plates BoM <a class="header-anchor" href="#plates-bom" aria-label="Permalink to &quot;Plates BoM&quot;">​</a></h1><p>The Plates Bill of Materials generates a PDF document listing all plate parts for your selected constructibles.</p><p><img src="'+s+'" alt="A page of a Plates BoM"></p><ol><li>The header of every page: project, status, date and batch, with your logo.</li><li>The material, finish and comment the table is for.</li><li>One row per plate, with zone subtotals and a total.</li><li>The plate drawings, numbered by the DWG Index of the table.</li></ol><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF (single file or ZIP with multiple PDFs)</li><li><strong>Content:</strong> All plate parts with dimensions, quantities, materials, and optional drawings. Plates are grouped by material, finish and comment. Each group has a <em>Clean Plates</em> table (plain rectangles) and a <em>Cutted Plates</em> table (plates with cuts or openings), with rows per zone, zone subtotals and a total of gross and net area.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Group parts from the report in the same folder</strong></td><td>How the content is split into files (see below). Default: <em>By Batch</em>.</td></tr><tr><td><strong>Combine</strong></td><td>When the output is a ZIP, also add <em>Combined.pdf</em> with all the PDFs merged.</td></tr><tr><td><strong>Cover Page</strong></td><td>Include a title page with project information. On by default.</td></tr><tr><td><strong>Designs Summary</strong></td><td>Add a summary table listing all included designs.</td></tr><tr><td><strong>Totals Table Page</strong></td><td>Add a page with the gross and net area per material, before the tables.</td></tr><tr><td><strong>Show Plates Drawings</strong></td><td>Include plate drawings in the report. On by default.</td></tr><tr><td><strong>Attach to Viewer as DOC</strong></td><td>Link each generated PDF to its assemblies in the Viewer. Only when the output is a ZIP.</td></tr><tr><td><strong>Contact person</strong> / <strong>Delivery address</strong></td><td>Printed on the cover page. Leave empty to use the company&#39;s.</td></tr><tr><td><strong>Materials</strong></td><td>Only include plates of the selected materials.</td></tr></tbody></table><h2 id="grouping-modes" tabindex="-1">Grouping Modes <a class="header-anchor" href="#grouping-modes" aria-label="Permalink to &quot;Grouping Modes&quot;">​</a></h2><ul><li><strong>By Selected Panels</strong> — One single PDF with all selected content.</li><li><strong>By Phase</strong> — One PDF per phase (ZIP output).</li><li><strong>By Batch</strong> — One PDF per batch (ZIP output).</li><li><strong>By Panel</strong> — One PDF per assembly (ZIP output).</li></ul><p>When you select by part batches, the output is always one single PDF.</p>',11),l=[n];function i(d,p,h,g,u,c){return e(),a("div",null,l)}const P=t(r,[["render",i]]);export{b as __pageData,P as default};
